/** The Terms sections, with the bare metal section when that product is public. */
export function termsSections(dedicatedPublic: boolean): LegalSection[] {
  if (!dedicatedPublic) return sections;
  const i = sections.findIndex((x) => x.heading === "Acceptable use");
  return i < 0 ? [...sections, DEDICATED_TERMS_SECTION] : [...sections.slice(0, i), DEDICATED_TERMS_SECTION, ...sections.slice(i)];
}
