                  className={`block rounded-lg px-3 py-2 text-sm transition-colors ${
                    l.href === current
                      ? "bg-white/[0.06] font-medium text-white"
                      : "text-slate-400 hover:bg-white/[0.03] hover:text-white"
                  }`}
                >
                  {l.label}
                </Link>
              ))}
            </nav>
          </div>
        </aside>

